const char* keur_logo(Bucket b, bool color) {
    switch (b) {
        case Bucket::Sm: return color ? k_logo_sm_color : k_logo_sm_mono;
        case Bucket::Md: return color ? k_logo_md_color : k_logo_md_mono;
        case Bucket::Lg: return color ? k_logo_lg_color : k_logo_lg_mono;
        case Bucket::Xl: return color ? k_logo_xl_color : k_logo_xl_mono;
    }
    return k_logo_md_mono;
}

